mapper.insert:

	SELECT  USER_ACCOUNT_SEQ.NEXTVAL
	FROM DUAL


INSERT INTO USER_ACCOUNT (USER_ID, LOGIN_ID, PASSWORD, NICKNAME)
VALUES (#{userId}, #{loginId}
	   , #{password}
	   , #{nickname})

mapper.select:
SELECT UA.USER_ID, UA.LOGIN_ID, UA.NICKNAME, UI.NAME, UI.EMAIL
  FROM USER_ACCOUNT UA
  JOIN USER_INFO UI ON UA.USER_ID = UI.USER_ID
 WHERE UI.NAME = #{name}
   AND UI.EMAIL = #{email}

SELECT UA.USER_ID, UA.LOGIN_ID, UA.NICKNAME, UI.NAME, UI.EMAIL
  FROM USER_ACCOUNT UA
  JOIN USER_INFO UI ON UA.USER_ID = UI.USER_ID
 WHERE UA.LOGIN_ID = #{loginId}
   AND UI.NAME = #{name}

mapper.update:
UPDATE USER_ACCOUNT
   SET PASSWORD = #{password}
 WHERE USER_ID = #{userId}

mapper.select:
SELECT PASSWORD
  FROM USER_ACCOUNT
 WHERE USER_ID = #{userId}
